<template><section class="accounts"><template v-if="adminAccount?.role==='OWNER'"><h2>관리자 계정·권한</h2><p>최고관리자: 전체 관리 · 심사 담당: 가입·프로필 심사 · 고객센터 담당: 문의·신고 처리 · 조회 전용: 조회만 가능</p><form @submit.prevent="create"><label>아이디<input v-model="username" required minlength="3" maxlength="80" autocomplete="off"/></label><label>초기 비밀번호<input type="password" v-model="password" required minlength="12" autocomplete="new-password"/></label><label>권한<select v-model="role"><option v-for="(label,value) in roles" :value="value">{{label}}</option></select></label><button :disabled="busy">관리자 추가</button></form><article v-for="a in accounts" :key="a.id"><strong>{{a.username}}</strong><span v-if="a.id===adminAccount.id"> (내 계정)</span><label>권한<select v-model="a.role"><option v-for="(label,value) in roles" :value="value">{{label}}</option></select></label><label><input type="checkbox" v-model="a.enabled"/>사용 가능</label><label>비밀번호 재설정<input type="password" v-model="a.password" autocomplete="new-password" placeholder="변경할 때만 입력 · 12자 이상"/></label><button :disabled="busy" @click="save(a)">저장·기존 세션 종료</button></article><h2>최근 관리자 활동 200건</h2><div class="audit"><p v-for="a in audits" :key="a.id">{{new Date(a.createdAt).toLocaleString('ko-KR')}} · {{a.username}} · {{a.action}} · {{a.status}}</p></div></template><h2>내 비밀번호 변경</h2><form @submit.prevent="changePassword"><label>현재 비밀번호<input type="password" v-model="currentPassword" autocomplete="current-password" required/></label><label>새 비밀번호<input type="password" v-model="newPassword" autocomplete="new-password" required minlength="12"/></label><button :disabled="busy">변경 후 로그아웃</button></form><p role="status">{{message}}</p></section></template>
<script setup>
import {ref,onMounted} from 'vue';import api from '../../api/api';import {adminAccount,clearAdmin} from '../../adminSession';
const emit=defineEmits(['logout']);const accounts=ref([]),audits=ref([]),busy=ref(false),message=ref(''),username=ref(''),password=ref(''),role=ref('READ_ONLY'),currentPassword=ref(''),newPassword=ref('');const roles={OWNER:'최고관리자',REVIEWER:'심사 담당',SUPPORT:'고객센터 담당',READ_ONLY:'조회 전용'};
async function load(){if(adminAccount.value?.role!=='OWNER')return;accounts.value=(await api.get('/admin/accounts')).data;audits.value=(await api.get('/admin/audit')).data;}
async function run(fn){if(busy.value)return;busy.value=true;message.value='';try{await fn();message.value='저장했습니다.';await load();}catch(e){message.value=e.response?.data?.message||'처리하지 못했습니다.';}finally{busy.value=false;}}
const create=()=>run(async()=>{await api.post('/admin/accounts',{username:username.value,password:password.value,role:role.value});username.value='';password.value='';});
const save=a=>run(async()=>{await api.put(`/admin/accounts/${a.id}`,{role:a.role,enabled:a.enabled,password:a.password||null});a.password='';if(a.id===adminAccount.value?.id){clearAdmin();emit('logout');}});
const changePassword=()=>run(async()=>{await api.post('/admin/session/password',{currentPassword:currentPassword.value,newPassword:newPassword.value});currentPassword.value='';newPassword.value='';clearAdmin();emit('logout');});
onMounted(()=>run(async()=>{}));
</script><style scoped>.accounts{background:white;border-radius:16px;padding:24px}.accounts form,.accounts article{display:flex;flex-wrap:wrap;align-items:end;gap:14px;padding:20px 0;border-bottom:1px solid #eee}.accounts label{display:grid;gap:6px;font-size:12px}.accounts input,.accounts select,.accounts button{padding:10px;border:1px solid #ddd;border-radius:8px}.accounts button{background:#bd7452;color:white;cursor:pointer}.accounts p{font-size:13px;color:#687585;line-height:1.7}.audit{max-height:360px;overflow:auto}.audit p{font-size:11px;overflow-wrap:anywhere}</style>
